@Environment(\.monarchTheme) private var theme
@State private var email = ""
@State private var isSigningIn = false

examples.code:
ScrollView {
    VStack(spacing: theme.spacing.space6) {
        Text("Product")
            .monarchTextStyle(.heading)
            .foregroundStyle(theme.colors.textDefault)
        MonarchCard {
            Text("Sign in").monarchTextStyle(.title).accessibilityAddTraits(.isHeader)
            Text("Use your work email to continue.")
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textMuted)
            MonarchTextField("Email", text: $email)
                .textContentType(.emailAddress)
            MonarchButton("Continue", variant: .primary, isLoading: isSigningIn, fullWidth: true) {
                isSigningIn = true
            }
        }
        Text("No account yet? Create one.")
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
        HStack(spacing: theme.spacing.space4) {
            if let terms = URL(string: "https://example.com/terms") {
                Link("Terms", destination: terms).buttonStyle(.monarchLink(.subtle))
            }
            if let privacy = URL(string: "https://example.com/privacy") {
                Link("Privacy", destination: privacy).buttonStyle(.monarchLink(.subtle))
            }
            if let help = URL(string: "https://example.com/help") {
                Link("Help", destination: help).buttonStyle(.monarchLink(.subtle))
            }
        }
        .monarchTextStyle(.caption)
    }
    .padding(theme.spacing.space4)
    .frame(maxWidth: theme.spacing.space24 * 5)
    .frame(maxWidth: .infinity)
}
.scrollDismissesKeyboard(.interactively)
.background(theme.colors.bgCanvas)
